const http = require('http');
const crypto = require('crypto');
const { OAUTH_LOOPBACK_PORT } = require('./shared-config');

const SUCCESS_PAGE = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Takeda</title>
<style>
  body{font-family:-apple-system,Segoe UI,sans-serif;background:#080B0F;color:#E7ECF2;
       height:100vh;margin:0;display:flex;align-items:center;justify-content:center;text-align:center}
  .card{padding:32px;background:#0B0F15;border:1px solid rgba(231,236,242,.09);border-radius:24px;box-shadow:0 12px 32px rgba(0,0,0,.3)}
  h1{font-size:22px;margin:0 0 12px;font-weight:600;}
  p{color:#8FA0AC;font-size:15px;margin:0}
  .icon{width:48px;height:48px;margin-bottom:16px;color:#54E7B3;}
</style></head>
<body><div class="card">
  <img src="data:image/png;base64," class="icon">
  <h1>Você pode fechar esta aba</h1><p>Voltando para o Takeda…</p>
</div>
<script>setTimeout(() => window.close(), 5000)</script>
</body></html>`;

const ERROR_PAGE = (msg) => `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Takeda</title>
<style>
  body{font-family:-apple-system,Segoe UI,sans-serif;background:#080B0F;color:#F2795C;
       height:100vh;margin:0;display:flex;align-items:center;justify-content:center;text-align:center}
  .card{padding:32px;background:#0B0F15;border:1px solid rgba(231,236,242,.09);border-radius:24px;box-shadow:0 12px 32px rgba(0,0,0,.3)}
  h1{font-size:22px;margin:0 0 12px;font-weight:600;}
  p{color:#8FA0AC;font-size:15px;margin:0}
  .icon{width:48px;height:48px;margin-bottom:16px;color:#F2795C;}
</style>
</head><body><div class="card">
  <img src="data:image/png;base64," class="icon">
  <h1>Não foi possível entrar</h1><p>${msg}</p>
</div></body></html>`;

// Tracks the currently listening loopback server (if any). A previous
// attempt — closed tab, a redirect that never arrived, etc. — can leave its
// server still bound to the port. Without cleanup, a retry's redirect can
// land on that stale server, which is still checking the OLD state value,
// producing a false "invalid login response". Each new attempt takes over
// the port cleanly instead of colliding with whatever came before it.
let activeServer = null;

function closeActiveServer() {
  if (activeServer) {
    try { activeServer.close(); } catch { /* already closed */ }
    activeServer = null;
  }
}

/**
 * Opens a one-shot local server on 127.0.0.1:OAUTH_LOOPBACK_PORT, waits for
 * Discord's redirect (?code=...&state=...), validates the state token to
 * guard against CSRF, then shuts itself down. Resolves with the auth code.
 */
function waitForDiscordRedirect(expectedState) {
  closeActiveServer();

  return new Promise((resolve, reject) => {
    const server = http.createServer((req, res) => {
      const url = new URL(req.url, `http://127.0.0.1:${OAUTH_LOOPBACK_PORT}`);
      if (url.pathname !== '/callback') {
        res.writeHead(404).end();
        return;
      }

      const code = url.searchParams.get('code');
      const state = url.searchParams.get('state');
      const error = url.searchParams.get('error');

      const done = (err, value) => {
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(err ? ERROR_PAGE(err) : SUCCESS_PAGE);
        clearTimeout(timeout);
        if (activeServer === server) activeServer = null;
        server.close();
        err ? reject(new Error(err)) : resolve(value);
      };

      if (error) return done('O Discord recusou a autorização.');
      if (!code || state !== expectedState) return done('Resposta de login inválida.');
      done(null, code);
    });

    server.on('error', (e) => {
      if (activeServer === server) activeServer = null;
      reject(e);
    });
    server.listen(OAUTH_LOOPBACK_PORT, '127.0.0.1');
    activeServer = server;

    // Don't hang forever if the user closes the browser tab without acting.
    const timeout = setTimeout(() => {
      if (activeServer === server) activeServer = null;
      server.close();
      reject(new Error('timeout'));
    }, 5 * 60 * 1000);
  });
}

function newState() {
  return crypto.randomBytes(16).toString('hex');
}

module.exports = { waitForDiscordRedirect, newState };
